import { cn } from "@/lib/utils";

/**
 * The sticker: just the QR code, centred. Sized in millimetres so it prints
 * true on an A4 3×8 label sheet (70 × 37 mm).
 */
export function DeviceLabel({ svg, className }: { svg: string; className?: string }) {
  return (
    <div className={cn("flex h-[37mm] w-[70mm] items-center justify-center overflow-hidden bg-white p-[3mm] text-black", className)}>
      <div
        className="size-[31mm] [&>svg]:size-full"
        // Generated by the qrcode library from our own URL, not user input.
        dangerouslySetInnerHTML={{ __html: svg }}
      />
    </div>
  );
}
